    food: { parent: 'lifestyle', label: 'Food and drink', path: /^(?:mat|food|oppskrifter|recipes|mat-og-drikke|essen|drikke|vin|wine)$/, labels: /\b(?:mat|oppskrift\w*|food|recipes?|vin|wine)\b/i },
